import {SCENARIOS,historyRows,snapshot} from './engine.js';
export const fmt=(v,n=2)=>Number(v).toLocaleString('en-US',{minimumFractionDigits:n,maximumFractionDigits:n});
export const time=t=>`${String(Math.floor(t/3600)).padStart(2,'0')}:${String(Math.floor(t%3600/60)).padStart(2,'0')}:${String(Math.floor(t%60)).padStart(2,'0')}`;
export const SENSORS={ph:{name:'pH ในน้ำหมัก',tag:'AIT-101',unit:'pH',description:'ค่าความเป็นกรด–ด่าง จำลองจาก VFA และความสามารถในการบัฟเฟอร์ของน้ำหมัก',hardware:'EZO-pH · I²C 0x63\nSCL / SDA: PB8 / PB9'},temp:{name:'อุณหภูมิน้ำหมัก',tag:'TT-101',unit:'°C',description:'อุณหภูมิของของเหลว เปลี่ยนตาม setpoint อย่างค่อยเป็นค่อยไปด้วย thermal inertia',hardware:'EZO-RTD · I²C 0x66\nSCL / SDA: PB8 / PB9'},gas:{name:'อัตราการเกิดก๊าซชีวภาพ',tag:'FT-101',unit:'L/h',description:'อัตราก๊าซรวมจากกระบวนการสร้างกรดและมีเทน ณ สภาวะวัดจำลอง ไม่ใช่ NL/h',hardware:'Pulse input\nPF15'},ch4:{name:'สัดส่วนมีเทน',tag:'AT-101',unit:'vol.% CH₄',description:'สัดส่วนมีเทนในก๊าซรวม อัตรามีเทนคำนวณจาก Biogas flow × CH₄ fraction',hardware:'สมมติ output: 4–20 mA\nผ่านวงจรรับเข้า → PA3'},mass:{name:'น้ำหนักสุทธิถังพัก',tag:'WT-101',unit:'kg',description:'น้ำหนักสุทธิของน้ำเสียที่เหลือในถังพัก โดยสมมติความหนาแน่น 1 kg/L ไม่ใช่มวลสะสมที่ป้อนแล้ว',hardware:'Load cell → ADS1232\nPF3 SCLK · PF4 DOUT\nPF5 PDWN'},orp:{name:'ศักย์รีดอกซ์ ORP',tag:'AIT-102',unit:'mV',description:'Proxy ของสภาวะรีดอกซ์จากกิจกรรมจุลินทรีย์ VFA และการกวน ไม่ใช่การวัด VFA หรือ COD โดยตรง',hardware:'EZO-ORP · I²C 0x62\nSCL / SDA: PB8 / PB9'},ec:{name:'ค่าการนำไฟฟ้า EC',tag:'AIT-103',unit:'mS/cm',description:'Proxy จาก buffer, VFA และสารด่างที่ผสมแล้ว ไม่ใช่การวัด VFA หรือ COD โดยตรง',hardware:'EZO-EC · I²C 0x64\nSCL / SDA: PB8 / PB9'}};
export function SimulationControls(r){return `<div class="control-bar"><div class="reactor-tabs" role="tablist" aria-label="เลือกถัง">${['R-101','R-102','R-103'].map(id=>`<button role="tab" aria-selected="${id===r.id}" class="${id===r.id?'active':''}" data-reactor="${id}"><i></i>${id}</button>`).join('')}</div><div class="control-group"><label for="scenario">SCENARIO</label><select id="scenario" class="scenario-select" aria-label="สถานการณ์ทดลอง">${SCENARIOS.map((s,i)=>`<option value="${i}" ${r.scenario===i?'selected':''}>${String.fromCharCode(65+i)}. ${s}</option>`).join('')}</select><button class="button small" id="apply-scenario" title="ใช้สถานการณ์ที่เลือกอีกครั้ง">↳ ใช้</button></div><div class="control-group"><button id="run" class="button primary small" ${r.running?'disabled':''}>▶ Run</button><button id="pause" class="button small" ${!r.running?'disabled':''}>Ⅱ Pause</button><button id="reset" class="button small" title="Reset เฉพาะถัง ${r.id}" aria-label="Reset ถังปัจจุบัน ${r.id}">↺</button><select id="speed" class="speed-select" title="1× = 1 วินาทีจริงต่อ 1 วินาทีจำลอง" aria-label="ความเร็ว simulation">${[1,60,360].map(n=>`<option ${r.speed===n?'selected':''}>${n}×</option>`).join('')}</select><div class="elapsed"><small>SIMULATION TIME</small><b id="elapsed">${time(r.t)}</b></div></div></div>`;}
const row=(label,key,unit='')=>`<div class="data-row"><span>${label}</span><b><span data-read="${key}"></span> ${unit}</b></div>`;
const toggle=(r,key,label)=>`<label class="toggle-row">${label}<input type="checkbox" class="switch" data-control="${key}" ${r.controls[key]?'checked':''}></label>`;
const input=(r,key,label,min,max,step)=>`<label class="input-field"><span>${label}</span><input type="number" data-control="${key}" value="${r.controls[key]}" min="${min}" max="${max}" step="${step}" required></label>`;
const head=(title,tag)=>`<div class="panel-eyebrow">${tag} / SIMULATED</div><div class="panel-heading"><h2>${title}</h2><button class="panel-close" id="close-panel" aria-label="กลับรายละเอียดถัง">×</button></div>`;
export function EquipmentPanel(r,key='reactor'){
 if(key==='reactor')return `<div class="panel-eyebrow">REACTOR DETAILS</div><div class="panel-heading"><h2>ถังปฏิกรณ์ ${r.id}</h2><span class="muted">↗</span></div><span class="mini-badge">● Simulated</span><div class="reactor-graphic"><span class="vessel-icon">♧</span><div><strong>20.0 <small>L</small></strong><small>ปริมาตรทำงาน / Working volume</small></div></div><div class="data-list">${row('Organic loading','loading','gCOD/L/d')}${row('ก๊าซสะสม','gasTotal','L')}${row('มีเทนสะสม','methaneTotal','L')}${row('น้ำเสียป้อนสะสม','feedTotal','L')}</div><div class="panel-section"><h3>สถานะอุปกรณ์ / EQUIPMENT</h3><div class="status-row"><span>ปั๊มป้อน P-101</span><span class="status-chip" data-status="pump"></span></div><div class="status-row"><span>มอเตอร์กวน M-101</span><span class="status-chip" data-status="mixer"></span></div><div class="status-row"><span>Heating jacket</span><span class="status-chip" data-status="heater"></span></div></div><p class="hint">แบบจำลองเพื่อการเรียนรู้<br>1× = 1 วินาทีจริง ต่อ 1 วินาทีจำลอง<br>กด Run เพื่อเริ่มทดลองถังนี้</p><button class="button panel-link" data-page="forecast">✧ เปิด AI Preview →</button>`;
 if(key==='pump')return head('ปั๊มป้อนน้ำเสีย','P-101')+`<p>ปรับภาระสารอินทรีย์เข้าสู่ถังหมัก</p>${toggle(r,'pump','เปิดปั๊มป้อน')}${input(r,'feed','อัตราป้อน · L/day',0,20,.1)}${input(r,'cod','COD น้ำเข้า · g/L',0,100,1)}<div class="data-list">${row('อัตราป้อนจริง','feed','L/day')}${row('ป้อนสะสม','feedTotal','L')}${row('Organic loading','loading','gCOD/L/d')}</div><p class="hint">ต้องเปิดปั๊มและวาล์ว และมีน้ำเสียในถังพัก จึงจะมีการไหล</p>`;
 if(key==='valve')return head('วาล์วป้อน','V-101')+toggle(r,'valve','เปิดวาล์ว')+row('อัตราป้อนจริง','feed','L/day')+'<p class="hint">วาล์วปิดจะหยุดน้ำป้อนทันที แต่ยังเกิดก๊าซจากสารอินทรีย์คงเหลือ</p>';
 if(key==='heater')return head('ระบบให้ความร้อน','HEATING JACKET')+toggle(r,'heater','เปิดระบบให้ความร้อน')+input(r,'target','อุณหภูมิเป้าหมาย · °C',15,55,.5)+row('อุณหภูมิจริง','temp','°C')+'<p class="hint">Thermal time constant 2 ชั่วโมงเมื่อเปิด และ 8 ชั่วโมงเมื่อปิด อุณหภูมิแวดล้อมสมมติ 25 °C</p>';
 if(key==='mixer')return head('ระบบกวน','M-101')+toggle(r,'mixer','เปิดมอเตอร์กวน')+`<label class="input-field"><span>ระดับการกวน · <b id="mix-level">${r.controls.mix}</b>%</span><input type="range" data-control="mix" min="0" max="100" step="5" value="${r.controls.mix}"></label><p class="hint">เป็นระดับการกวนจำลอง ไม่ใช่ RPM จริง การกวนมีผลต่ออัตราปฏิกิริยาและเวลาผสมสารด่าง</p>`;
 if(key==='alk')return head('จ่ายสารด่าง','TK-102 / P-102')+`<p>ความเข้มข้นในแบบจำลอง<br><b>50 g CaCO₃-equivalent/L</b></p><label class="input-field"><span>ปริมาณเติมครั้งนี้ · mL</span><input id="dose-amount" type="number" min="1" max="500" value="100"></label><button id="dose" class="button primary" style="width:100%">+ เติมสารด่าง</button><div class="data-list">${row('เติมสะสม','alkTotal','L')}${row('สารด่างรอผสม','pendingAlk','mL')}${row('สารด่างคงเหลือ','alkTank','L')}${row('pH ปัจจุบัน','ph','pH')}${row('EC ปัจจุบัน','ec','mS/cm')}</div><p class="hint">การผสมใช้เวลาคงตัว 9 นาทีเมื่อเปิดกวน / 36 นาทีเมื่อปิด pH และ EC จึงไม่กระโดดทันที</p>`;
 if(key==='feedTank')return head('ถังพักน้ำเสีย','TK-101')+`<p>น้ำเสียโรงงานแป้ง · ความจุเริ่มต้น 50 L</p><div class="data-list">${row('ปริมาตรคงเหลือ','feedVolume','L')}${row('น้ำหนักสุทธิ','mass','kg')}${row('ป้อนสะสม','feedTotal','L')}</div><p class="hint">ความหนาแน่นสมมติ 1 kg/L น้ำเสียลดลงตามปริมาณที่ป้อนจริง ถังว่างแล้วการป้อนหยุด</p><button data-equip="pump" class="button panel-link">ปรับปั๊มป้อน P-101 →</button>`;
 if(key==='gas')return head('ถังเก็บก๊าซ','G-101')+`<p>ก๊าซที่ผลิตทั้งหมดสะสมในถังเก็บเชิงแนวคิด ไม่มีการระบายหรือใช้ก๊าซในแบบจำลองนี้</p><div class="data-list">${row('ก๊าซสะสม','gasTotal','L')}${row('มีเทนสะสม','methaneTotal','L')}${row('อัตรามีเทน','methane','L/h')}</div><p class="hint">ปริมาตร ณ สภาวะวัดจำลอง ไม่ใช่ NL<br>สะสมด้วยการ integrate อัตราจริงภายในแบบจำลอง ไม่ใช้ % CH₄ แทนปริมาตร</p>`;
 if(key==='sample')return head('จุดเก็บตัวอย่าง','SIMULATION STATE')+`<p>ค่าภายในแบบจำลอง ไม่ใช่หัววัดจริง และไม่รวมในรายการเซนเซอร์ทั้ง 7 จุด</p><div class="data-list">${row('VFA','vfa','gCOD-eq/L')}${row('Alkalinity','alk','gCaCO₃-eq/L')}${row('สารอินทรีย์พร้อมย่อย','substrate','gCOD/L')}${row('กิจกรรม methanogen','activity','')}</div><p class="hint">การตรวจตัวอย่างจริงต้องอาศัยการวิเคราะห์ในห้องปฏิบัติการ ORP และ EC ไม่สามารถวัด VFA/COD โดยตรง</p>`;
 if(key==='effluent')return head('ถังรับน้ำทิ้ง','TK-103')+row('น้ำออกสะสม','effluent','L')+row('ปริมาตรถังหมัก','volume','L')+'<p class="hint">สมมติการไหลล้น: น้ำออกเท่ากับน้ำป้อนรวมสารด่างที่ผสมเข้าสู่ถัง เพื่อรักษาปริมาตรทำงาน 20 L ถังรับเป็นภาชนะสะสมเชิงแนวคิด ไม่จำลองความจุสูงสุด</p>';
 return head('ชุดแยกหยดน้ำ','MOISTURE SEPARATOR')+'<p>แสดงตำแหน่งการแยกหยดน้ำก่อนวัดก๊าซ เป็นภาพประกอบ ไม่จำลองสมดุลไอน้ำหรือการควบแน่น</p>';
}
export function SensorPanel(key,tab='reading'){const s=SENSORS[key];return head(s.name,s.tag)+`<span class="mini-badge">● Simulated sensor</span><div class="sensor-big"><span data-read="${key}"></span> <small>${s.unit}</small></div><div class="tab-strip"><button data-sensor-tab="reading" class="${tab==='reading'?'active':''}">ค่าตรวจวัด</button><button data-sensor-tab="hardware" class="${tab==='hardware'?'active':''}">Hardware concept</button></div>${tab==='hardware'?`<p>Controller concept<br><b>NUCLEO-H7S3L8</b></p><div class="hardware-info">${s.hardware.replaceAll('\n','<br>')}</div><p class="hint">เป็นแนวคิดอินเทอร์เฟซเท่านั้น เวอร์ชันนี้ไม่มีการเชื่อมต่อฮาร์ดแวร์</p>`:`<p>${s.description}</p><div id="sensor-chart"></div><div class="chart-label">แกน X: ชั่วโมงจำลอง · ช่วงเดียวกับกราฟหลัก</div><p class="hint">ค่าที่อ่านมี measurement noise ขนาดเล็กจาก seed คงที่ ค่าจริงภายใน simulation เก็บแยกต่างหาก</p>`}`;}
export const CHARTS={gas:{title:'อัตราก๊าซ',keys:['gas','methane'],labels:['Biogas','Methane'],unit:'L/h'},ch4:{title:'CH₄ concentration',keys:['ch4'],labels:['CH₄'],unit:'vol.%'},ph:{title:'pH',keys:['ph'],labels:['pH'],unit:'pH'},temp:{title:'Temperature',keys:['temp'],labels:['Temperature'],unit:'°C'},orp:{title:'ORP',keys:['orp'],labels:['ORP proxy'],unit:'mV'},ec:{title:'EC',keys:['ec'],labels:['EC proxy'],unit:'mS/cm'},feed:{title:'Feed rate',keys:['feed'],labels:['Feed'],unit:'L/day'},feedTotal:{title:'Cumulative feed',keys:['feedTotal'],labels:['Feed total'],unit:'L'},vfa:{title:'Simulation state · VFA',keys:['vfa'],labels:['VFA (model state)'],unit:'gCOD-eq/L'},alk:{title:'Simulation state · Alkalinity',keys:['alk'],labels:['Buffer (model state)'],unit:'gCaCO₃-eq/L'}};
export const colors=['#acd68b','#68b8e4','#b59ae0'];
export function Chart(rows,keys,unit,{width=1000,height=160,forecastAt=null}={}){
 if(rows.length<2)return '<div class="empty">ยังไม่มีประวัติเพียงพอ · กด Run เพื่อเริ่มเก็บข้อมูล</div>';
 const left=50,right=16,top=15,bottom=27;const vals=rows.flatMap(r=>keys.map(k=>r[k])).filter(Number.isFinite);if(!vals.length)return '<div class="empty">ยังไม่มีข้อมูลเปรียบเทียบ</div>';
 let low=Math.min(...vals),high=Math.max(...vals);const padding=Math.max((high-low)*.15,Math.abs(high)*.025,.02);low-=padding;high+=padding;
 const start=rows[0].time,end=Math.max(start+1,rows.at(-1).time),x=t=>left+(t-start)/(end-start)*(width-left-right),y=v=>height-bottom-(v-low)/(high-low)*(height-bottom-top);
 let result=`<svg class="chart" viewBox="0 0 ${width} ${height}" preserveAspectRatio="none" role="img" aria-label="กราฟ ${keys.join(', ')} หน่วย ${unit} เทียบชั่วโมงจำลอง"><title>${keys.join(', ')} (${unit}) · simulation hours</title>`;
 for(let i=0;i<4;i++){const v=low+(high-low)*i/3;result+=`<line class="grid" x1="${left}" x2="${width-right}" y1="${y(v)}" y2="${y(v)}"/><text x="${left-8}" y="${y(v)+3}" text-anchor="end">${fmt(v,Math.abs(v)>100?0:2)}</text>`;}
 for(let i=0;i<5;i++){const t=start+(end-start)*i/4;result+=`<text x="${x(t)}" y="${height-6}" text-anchor="middle">${fmt(t/3600,2)}h</text>`;}
 const stride=Math.max(1,Math.floor(rows.length/600)),sample=rows.filter((_,i)=>i%stride===0||i===rows.length-1);
 keys.forEach((k,i)=>{let d='',prev=false;for(const p of sample){if(Number.isFinite(p[k])){d+=`${prev?'L':'M'}${x(p.time).toFixed(2)},${y(p[k]).toFixed(2)} `;prev=true;}else prev=false;}result+=`<path d="${d}" stroke="${colors[i]}" class="line" ${k==='predicted'?'stroke-dasharray="6 5"':''}/>`;});
 if(forecastAt!==null)result+=`<line x1="${x(forecastAt)}" x2="${x(forecastAt)}" y1="10" y2="${height-bottom}" stroke="#a6b8c5" stroke-dasharray="3 4"/>`;
 return result+'</svg>';
}
export function TrendCharts(key,hours,expanded,mode){return `<div class="trend-top"><div class="trend-title"><h2>แนวโน้มกระบวนการ</h2><small>PROCESS TRENDS</small></div><div class="control-group"><div class="segments" aria-label="ช่วงเวลาของกราฟและ CSV">${[6,12,24,0].map(n=>`<button data-hours="${n}" class="${n===hours?'active':''}">${n?n+'h':'ทั้งหมด'}</button>`).join('')}</div><button id="expand-trend" class="text-button">${expanded?'⌃ ย่อ':'⌄ ขยาย'}</button></div></div><div class="tab-strip trend-tabs"><button data-trend-tab="sensors" class="${!['vfa','alk'].includes(key)?'active':''}">ค่าตรวจวัด / Process</button><button data-trend-tab="state" class="${['vfa','alk'].includes(key)?'active':''}">Simulation state</button></div><div class="trend-options"><div class="chart-legend">${CHARTS[key].labels.map((l,i)=>`<span><i style="background:${colors[i]}"></i>${l} <span class="muted">(${CHARTS[key].unit})</span></span>`).join('')}</div><div class="control-group"><select id="chart-select" class="trend-select" aria-label="ตัวแปรกราฟ">${Object.entries(CHARTS).map(([k,v])=>`<option value="${k}" ${key===k?'selected':''}>${v.title}</option>`).join('')}</select><button id="toggle-table" class="text-button">${mode==='chart'?'▦ ตาราง':'∿ กราฟ'}</button></div></div><div id="chart-body" style="${expanded?'min-height:280px':''}"></div><div class="chart-label">แกน X: เวลา simulation (ชั่วโมง) · ประวัติทุก 1 นาที + ค่าปัจจุบัน · เก็บล่าสุด 7 วันจำลอง · CSV ใช้ช่วงเวลาที่เลือก</div>`;}
export function DataTable(rows,key){const c=CHARTS[key];return `<div class="table-scroll"><table><thead><tr><th>Simulation time</th>${c.labels.map(l=>`<th>${l} (${c.unit})</th>`).join('')}</tr></thead><tbody>${rows.slice(-500).reverse().map(r=>`<tr><td>${time(r.time)}</td>${c.keys.map(k=>`<td>${fmt(r[k],4)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="chart-label">ตารางแสดงล่าสุดไม่เกิน 500 แถวในช่วงที่เลือก · CSV ส่งออกทุกแถวในช่วง</div>`;}
export function EventLog(r){return `<article class="content-card"><div class="panel-eyebrow">${r.id} / EVENT LOG</div><h2>บันทึกเหตุการณ์</h2><p>เวลาที่แสดงเป็นเวลา simulation ของถังนี้ · เก็บล่าสุด 500 เหตุการณ์</p>${r.events.map(e=>`<div class="event-item"><time>${time(e.t)}</time><span>${e.message}</span></div>`).join('')}</article>`;}
export function ForecastPanel(r){const f=r.forecasts.at(-1);return `<article class="content-card"><div class="panel-eyebrow">${r.id} / FORECAST EXPERIMENT</div><h2>AI Preview — ตัวอย่างแนวคิด</h2><p>แนวโน้ม methane flow ใน 6 ชั่วโมงข้างหน้า จาก simplified-model forecast</p><div class="forecast-grid"><div><div class="forecast-chart" id="forecast-chart"></div><div class="chart-legend"><span><i style="background:${colors[0]}"></i>คาดการณ์ (เส้นประ) · L/h</span><span><i style="background:${colors[1]}"></i>ค่าจริงภายใน simulation · L/h</span></div><p class="hint">${f?`ออกคำคาดการณ์เมื่อ ${time(f.issued)} · คงการตั้งค่าขณะออกคำคาดการณ์ไว้ตลอด 6 ชั่วโมง`:'กดสร้างคำคาดการณ์เพื่อจำลองอนาคตจากสถานะปัจจุบัน'}</p></div><div><h3>ข้อมูลที่ใช้ประกอบ</h3><p>อัตราป้อน · COD น้ำเข้า · VFA · alkalinity · กิจกรรมจุลินทรีย์ · อุณหภูมิ · การกวน · สารด่างที่รอผสม</p><button id="forecast" class="button primary panel-link">✧ สร้างคำคาดการณ์ 6 ชั่วโมง</button><p class="hint">ใช้สมการเดียวกับ simulation ไม่ใช่ ML ที่ฝึกแล้ว และยังไม่ผ่าน validation กับถังจริง ไม่มีการสั่งงานอุปกรณ์จากคำคาดการณ์นี้</p></div></div><h3>เปรียบเทียบหลังเวลาจำลองเดินถึงจุดคาดการณ์</h3><div id="forecast-comparison"></div></article>`;}
export function forecastRows(r){const f=r.forecasts.at(-1);if(!f)return [];const actual=historyRows(r);return f.points.map(p=>{let closest=null;for(const a of actual)if(Math.abs(a.time-p.time)<=30&&(!closest||Math.abs(a.time-p.time)<Math.abs(closest.time-p.time)))closest=a;return {time:p.time,predicted:p.methane,actual:p.time<=r.t?closest?.trueMethane:undefined};});}
export function ModelAssumptions(){return `<article class="content-card"><div class="panel-eyebrow">EDUCATIONAL MODEL / v1.0</div><h2>Model assumptions — สมมติฐานของแบบจำลอง</h2><p>แบบจำลองย่อยสลายสองขั้นแบบรวม เพื่อแสดงความสัมพันธ์และเวลาตอบสนอง ไม่ใช่ ADM1 และไม่ได้ผ่านการตรวจสอบกับถังจริง</p><div class="model-grid"><div><h3>สมการย่อ</h3><div class="equations">Q = pump × valve × feed / 24 (L/h)<br>D = (Q + Qalk) / V (h⁻¹)<br>rₐ = 0.08 · S · fT · fMix<br>rₘ = 0.12 · X · A/(0.3+A) · fT · fpH · fMix<br>dS/dt = Q·CODin/V − D·S − rₐ<br>dA/dt = rₐ − rₘ − D·A<br>dB/dt = (2.5Q + 50Qalk)/V − D·B<br>pH = clamp(7.35 − 0.95A/max(0.2,B), 4.5, 8.5)<br>fT = exp(−((T−35)/16)²)<br>fpH = 1 / (1 + ((pH−7.05)/0.85)⁴)<br>fMix = 0.65 + 0.35·level/100 (เปิดกวน)<br>fMix = 0.35 (ปิดกวน)<br>dX/dt = (0.95·fT·fpH − X)/12<br>dT/dt = (Ttarget−T)/τ + Q·(25−T)/V<br>CH₄ = 0.33 · rₘ · V (L/h)<br>CO₂ = (0.19rₐ + 0.04rₘ) · V (L/h)<br>Biogas = CH₄ + CO₂<br>CH₄ fraction = CH₄ / Biogas<br>Gas accumulated = ∫ Biogas dt<br>Methane accumulated = ∫ CH₄ dt</div><p class="hint">S: สารอินทรีย์พร้อมย่อย, A: VFA (gCOD-equivalent/L), B: buffer (gCaCO₃-equivalent/L), X: กิจกรรมจุลินทรีย์แบบไร้หน่วย, V: ปริมาตรน้ำหมัก (L)</p><h3>ORP และ EC เป็น proxy</h3><div class="equations">ORP = −310 − 55X + 14A + 8(1−fMix) mV<br>EC = 2.1 + 0.42B + 0.12A + 0.3Z mS/cm<br>dZ/dt = 50Qalk/V − D·Z</div><p>Z คือเกลือสมมติที่เพิ่มจากสารด่าง ทั้งสองสมการเป็นความสัมพันธ์เพื่อสาธิต ไม่ใช่วิธีตรวจ VFA หรือ COD</p></div><div><h3>พารามิเตอร์และหน่วย</h3><div class="table-scroll"><table><thead><tr><th>พารามิเตอร์</th><th>ค่าเริ่มต้น / หน่วย</th></tr></thead><tbody><tr><td>Working volume / ถังพัก</td><td>20 / 50 L</td></tr><tr><td>Feed / COD น้ำเข้า</td><td>2 L/day / 20 gCOD/L</td></tr><tr><td>S / VFA</td><td>0.99 / 0.60 gCOD-eq/L</td></tr><tr><td>Buffer / กิจกรรม X</td><td>2.50 gCaCO₃-eq/L / 0.90</td></tr><tr><td>Temperature / ambient</td><td>35 / 25 °C</td></tr><tr><td>Acid formation k / methanogenesis max</td><td>0.08 h⁻¹ / 0.12 gCOD/L/h</td></tr><tr><td>VFA half-saturation</td><td>0.30 gCOD/L</td></tr><tr><td>Activity adaptation</td><td>12 h</td></tr><tr><td>Thermal τ เปิด / ปิด</td><td>2 / 8 h</td></tr><tr><td>Alk concentration / reservoir</td><td>50 gCaCO₃-eq/L / 2 L</td></tr><tr><td>Mixing τ เปิด / ปิด</td><td>0.15 / 0.60 h</td></tr><tr><td>Gas yield CH₄ / CO₂ terms</td><td>0.33 / 0.19, 0.04 L/gCOD</td></tr><tr><td>Feed density</td><td>1 kg/L</td></tr><tr><td>Numerical timestep</td><td>1 second (fixed Euler)</td></tr></tbody></table></div><p class="hint">พารามิเตอร์และสัมประสิทธิ์ตัวเลขทั้งหมดข้างต้นตั้งขึ้นเพื่อสาธิต ไม่ใช่ค่าที่สอบเทียบกับน้ำเสียโรงงานแป้งหรือถังจริง</p><h3>สมมติฐานและข้อจำกัด</h3><ul><li>ถังผสมสมบูรณ์ ปริมาตรทำงานคงที่ น้ำออกเท่ากับน้ำเข้าและสารด่างที่ผสม น้ำออกสะสมในถังรับเชิงแนวคิด</li><li>สารด่างที่กดเติมเข้าสู่คิวผสมก่อน จึงไม่เปลี่ยน buffer หรือ EC ทันที</li><li>ไม่จำลององค์ประกอบจุลินทรีย์ สมดุลคาร์บอเนต แอมโมเนีย แรงดัน ไอน้ำ หรือความจุถังเก็บก๊าซ</li><li>ก๊าซเป็น L ณ สภาวะวัดจำลอง ไม่ใช่ NL ผลผลิตต่อ COD เป็นค่าสาธิต</li><li>pH, ORP และ EC เป็นสมการ proxy ไม่มีการแก้สมดุลประจุ</li><li>Noise จาก LCG seed คงที่ เปลี่ยนทุก 10 วินาที: pH ±0.003, T ±0.01 °C, gas ±0.2%, CH₄ ±0.04 จุดเปอร์เซ็นต์, mass ±0.001 kg, ORP ±0.2 mV, EC ±0.002 mS/cm</li><li>ค่าป้าย กราฟ และ CSV มาจาก snapshot เดียวกัน ค่าสะสม integrate อัตราจริงก่อน noise โดย CSV มี trueGas/trueMethane/truePH แยกไว้</li><li>ทุกความเร็วใช้ timestep 1 วินาทีเดียวกัน เมื่อซ่อนแท็บหรือปิดหน้า เวลาไม่เดินออฟไลน์ เปิดใหม่ในสถานะ Pause</li><li>แต่ละถังรักษาค่าตั้งและประวัติอิสระ เก็บข้อมูลในเบราว์เซอร์และประวัติย้อนหลังสูงสุด 7 วันจำลอง</li></ul></div></div><h3>แหล่งอ้างอิงสำหรับหลักการ</h3><p>ใช้ประกอบความสัมพันธ์เชิงแนวคิด ไม่ได้ใช้รับรองตัวเลขพารามิเตอร์ของเว็บนี้</p><ul><li><a href="https://www.epa.gov/anaerobic-digestion/frequent-questions-about-anaerobic-digestion" target="_blank" rel="noopener">US EPA — Frequent Questions about Anaerobic Digestion</a> · องค์ประกอบก๊าซและกระบวนการย่อย</li><li><a href="https://extension.umd.edu/resource/anaerobic-digestion-ebr-2023-0686" target="_blank" rel="noopener">University of Maryland Extension — Anaerobic Digestion</a> · ขั้นการย่อยและปัจจัยที่มีผล</li><li><a href="https://iwaponline.com/ebooks/book/152/Anaerobic-Digestion-Model-No-1-ADM1" target="_blank" rel="noopener">IWA — Anaerobic Digestion Model No. 1 (ADM1)</a> · อ้างอิงขอบเขตแบบจำลองมาตรฐาน เว็บนี้ไม่ได้ implement ADM1</li></ul><p class="hint">Scenario A–E เป็นการสาธิตเพื่อการเรียนรู้ ไม่ใช่คำแนะนำการเดินระบบจริง · Hardware concept และ AI Preview เป็นตัวอย่างแนวคิด ไม่มีการเชื่อมต่อ STM32/MQTT และไม่มีโมเดล ML ที่ผ่าน validation</p></article>`;}
